selected.compute:
options = read('/input/options')
result = []
for combo in combinations(options, 2):
    ids = [record['id'] for record in combo]
    if valid(ids):
        result = ids
        break
if not result:
    for combo in combinations(options, 3):
        ids = [record['id'] for record in combo]
        if valid(ids):
            result = ids
            break
if not result:
    for combo in combinations(options, 4):
        ids = [record['id'] for record in combo]
        if valid(ids):
            result = ids
            break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        result = selection
    else:
        result = []
if result and not exists('/output/selection'):
    write('/output/selection', result)
if result and status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
